#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353LL;

long long power(long long base, long long exp) {
    long long result = 1LL;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l, r;
    cin >> n >> m >> l >> r;

    if ((n * m & 1) == 1) {
        cout << power(r - l + 1, n * m) << "\n";
        return 0;
    }

    long long E = r / 2 - (l - 1) / 2;
    long long O = r - l + 1 - E;

    long long ans = (power(E + O, n * m) + power(E - O, n * m)) % mod;
    ans = (ans * power(2, mod - 2)) % mod;

    cout << ans << "\n";

    return 0;
}
